create extension if not exists pgcrypto;
do $$ begin create type public.user_role as enum ('tenant','landlord','student','admin','moderator'); exception when duplicate_object then null; end $$;
do $$ begin create type public.complaint_status as enum ('submitted','acknowledged','in_progress','resolved','escalated','closed'); exception when duplicate_object then null; end $$;
do $$ begin create type public.dispute_status as enum ('open','awaiting_response','mediation','referred','resolved','closed'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',phone text,role public.user_role not null default 'tenant',preferred_language text not null default 'en',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.properties(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,title text not null,property_type text not null,address text not null,city text not null,region text not null,bedrooms integer not null default 1 check(bedrooms>=0),monthly_rent numeric(12,2) not null check(monthly_rent>=0),currency text not null default 'GHS',description text,status text not null default 'active',created_at timestamptz not null default now());
create table if not exists public.tenancies(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties(id) on delete cascade,tenant_id uuid not null references public.profiles(id) on delete cascade,landlord_id uuid not null references public.profiles(id) on delete cascade,start_date date not null,end_date date,rent_amount numeric(12,2) not null check(rent_amount>=0),payment_frequency text not null default 'monthly',agreement_document_path text,status text not null default 'active',created_at timestamptz not null default now());
create table if not exists public.rent_receipts(id uuid primary key default gen_random_uuid(),tenancy_id uuid not null references public.tenancies(id) on delete cascade,payer_id uuid not null references public.profiles(id),amount numeric(12,2) not null check(amount>0),paid_at timestamptz not null default now(),payment_method text not null,transaction_reference text,receipt_file_path text,notes text,created_at timestamptz not null default now());
create table if not exists public.complaints(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id) on delete cascade default auth.uid(),property_id uuid references public.properties(id) on delete set null,category text not null,description text not null check(char_length(description)>=10),status public.complaint_status not null default 'submitted',assigned_to uuid references public.profiles(id) on delete set null,is_anonymous_to_property_owner boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.complaint_evidence(id uuid primary key default gen_random_uuid(),complaint_id uuid not null references public.complaints(id) on delete cascade,uploaded_by uuid not null references public.profiles(id) on delete cascade default auth.uid(),storage_path text not null,media_type text,created_at timestamptz not null default now());
create table if not exists public.disputes(id uuid primary key default gen_random_uuid(),complaint_id uuid references public.complaints(id) on delete set null,opened_by uuid not null references public.profiles(id) on delete cascade default auth.uid(),other_party_id uuid references public.profiles(id) on delete set null,summary text not null,status public.dispute_status not null default 'open',response_due_at timestamptz,resolution_note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.rent_assessment_requests(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties(id) on delete cascade,submitted_by uuid not null references public.profiles(id) on delete cascade default auth.uid(),proposed_rent numeric(12,2) not null check(proposed_rent>=0),property_details jsonb not null default '{}'::jsonb,status text not null default 'draft',official_reference text,official_outcome_note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists properties_owner_idx on public.properties(owner_id);
create index if not exists tenancies_tenant_idx on public.tenancies(tenant_id);
create index if not exists tenancies_landlord_idx on public.tenancies(landlord_id);
create index if not exists complaints_reporter_idx on public.complaints(reporter_id);
create index if not exists complaints_status_idx on public.complaints(status);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict(id) do nothing; return new; end $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.properties enable row level security; alter table public.tenancies enable row level security; alter table public.rent_receipts enable row level security; alter table public.complaints enable row level security; alter table public.complaint_evidence enable row level security; alter table public.disputes enable row level security; alter table public.rent_assessment_requests enable row level security;
drop policy if exists "Profiles are viewable by their owner" on public.profiles;
create policy "Profiles are viewable by their owner" on public.profiles for select using(id=(select auth.uid()));
drop policy if exists "Users update their own basic profile" on public.profiles;
create policy "Users update their own basic profile" on public.profiles for update using(id=(select auth.uid())) with check(id=(select auth.uid()));
drop policy if exists "Owners manage their properties" on public.properties;
create policy "Owners manage their properties" on public.properties for all using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
drop policy if exists "Tenancy parties can view tenancy" on public.tenancies;
create policy "Tenancy parties can view tenancy" on public.tenancies for select using(tenant_id=(select auth.uid()) or landlord_id=(select auth.uid()));
drop policy if exists "Users create complaints" on public.complaints;
create policy "Users create complaints" on public.complaints for insert to authenticated with check(reporter_id=(select auth.uid()));
drop policy if exists "Reporters view their complaints" on public.complaints;
create policy "Reporters view their complaints" on public.complaints for select to authenticated using(reporter_id=(select auth.uid()));
